head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setDataDragSelectAutoScroll]<br/>GridView 컴포넌트의 dataDragSelectAutoScroll 속성을 설정합니다.",
    "validation" : [
        "dataDragSelect=true, useShiftKey=true 이고, dataDragDrop, dataDragDropSelf, dataDragDropOther, dataDragDropCell 속성이 모두 false 인 경우에 dataDragSelectAutoScroll 속성이 적용됩니다.",
        "dragSelectAutoScroll(필수) 파라미터를 true 로 설정 시 마우스로 Drag 하여 다중 Cell 선택 시 자동으로 스크롤됩니다.",
        "dragSelectAutoScroll(필수) 파라미터를 false 로 설정 시 마우스로 Drag 하여 다중 Cell 선택 시 자동으로 스크롤되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof target1 !== 'undefined') { target1.remove(); }
    if (typeof dlt_src !== 'undefined') { $p.data.remove("dlt_src"); }

    // 사용법 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  - target1 은 dataDragSelect=true / useShiftKey=true 고정(전제) + dataDragDrop/Self/Other/Cell 미부여(기본 false) 로 생성.
    //  - dataDragSelectAutoScroll 은 초기 미설정(기본 false). [setDataDragSelectAutoScroll] 버튼으로 par_dragSelectAutoScroll 값(true/false)을 적용.
    //  - true 적용 시 Body Cell 을 Drag 한 채 GridView 영역 밖으로 이동하면 자동 세로 스크롤. 설정 결과는 getDataDragSelectAutoScroll() 반환값으로 확인.
    $c.gcm.createLabel('label="dataDragSelect=true / useShiftKey=true 고정(전제). [setDataDragSelectAutoScroll] 로 par_dragSelectAutoScroll 값 적용(getDataDragSelectAutoScroll 로 확인). true 면 Body Cell 을 Drag 한 채 그리드 하단 밖으로 유지 시 자동 세로 스크롤."', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // === DataList(dlt_src) : 4 Column / 30행 (뷰포트보다 많게 → 세로 스크롤 발생) ===
    let strSrc = '';
    strSrc += '<w2:dataList ' + strNameSpace + ' id="dlt_src" baseNode="list" repeatNode="map">';
    strSrc += '<w2:columnInfo>';
    strSrc += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strSrc += '</w2:columnInfo>';
    strSrc += '<w2:data use="true"></w2:data>';
    strSrc += '</w2:dataList>';
    $p.data.create(strSrc);

    // 데이터 30행 로드 (grid height 보다 많은 행 → 세로 스크롤 발생)
    let srcData = [];
    for (let i = 1; i <= 30; i++) {
        srcData.push({ "col1": "행" + i, "col2": (i * 100) + "", "col3": "C" + i, "col4": (i * 10) + "" });
    }
    dlt_src.setJSON(srcData, false);

    let grp_comp = $c.gcm.getTestGroup();

    // === target1 : dataDragSelect=true / useShiftKey=true 고정 / dataDragSelectAutoScroll 미설정(기본 false) ===
    //  - dataDragDrop 계열은 전부 미부여(기본 false) → dataDragSelectAutoScroll 동작 전제 충족
    let srcCList = $c.gcm.createCList({ dataList: "data:dlt_src", dataDragSelect: true, useShiftKey: true });

    let strTarget1 = '';
    strTarget1 += '<w2:gridView ' + strNameSpace + ' ' + srcCList + ' id="" style="width:440px;height:150px;">';
    strTarget1 += '<w2:caption style="" id="caption1" value="target1 (setDataDragSelectAutoScroll 테스트 / dataDragSelect=true, useShiftKey=true)"></w2:caption>';
    strTarget1 += '<w2:header style="" id="header1">';
    strTarget1 += '<w2:row style="" id="hrow1">';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:header>';
    strTarget1 += '<w2:gBody style="" id="gBody1">';
    strTarget1 += '<w2:row style="" id="brow1">';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col2" dataList="col2"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    strTarget1 += '<w2:column width="100" style="" inputType="text" dataType="text" id="col4" dataList="col4"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:gBody>';
    strTarget1 += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget1, grp_comp);
};



// [setDataDragSelectAutoScroll] : par_dragSelectAutoScroll 값(true/false)을 Boolean 으로 target1 에 적용
//  - 설정 직후 쌍 get 메소드 getDataDragSelectAutoScroll() 호출로 반영 여부 확인 (§5 set 검증 규칙)
//  - true 설정 시 dataDragSelect=true + useShiftKey=true 전제 하에 Body Cell 을 Drag 한 채 영역 밖 이동 시 자동 세로 스크롤 (사용자 수동 Drag)
scwin.btn_setDataDragSelectAutoScroll_onclick = function () {
    let dragSelectAutoScroll = par_dragSelectAutoScroll.getText() === "true";

    target1.setDataDragSelectAutoScroll(dragSelectAutoScroll);

    let b = wf_body_bottom.getObj("scwin");
    b.setReturnValue("setDataDragSelectAutoScroll(" + dragSelectAutoScroll + ") 호출");
    b.setReturnValue("getDataDragSelectAutoScroll() 반환값 : " + target1.getDataDragSelectAutoScroll());
};



// 세로 스크롤 위치(px) 조회 헬퍼 (GridView 세로 스크롤 컨테이너 DOM)
scwin.getScrollTopPx = function () {
    let div = document.querySelector("[id$='target1_scrollY_div']");
    return div ? Math.round(div.scrollTop) : -1;
};

// [스크롤 위치 출력] : 자동 스크롤로 세로 스크롤 위치가 이동했는지 확인
//  - Drag 전 scrollTop=0 → true 설정 + Body Cell 을 Drag 한 채 영역 밖 이동(자동 스크롤) 후 scrollTop 증가(이동 여부 true)
scwin.btn_scrollPos_onclick = function () {
    let top = scwin.getScrollTopPx();
    wf_body_bottom.getObj("scwin").setReturnValue("현재 세로 스크롤 위치(scrollTop) : " + top + "px / 스크롤 이동 여부 : " + (top > 0));
};
